import {COW,COW_LEDGER_TYPES,COW_ORDERS} from './cow-config.js';import {cowCoolerStatus} from './cow-storage.js';
/** Reconcile persisted economic facts with actual source transactions. This is a consistency boundary, not authenticated cloud anti-cheat. @param {import('./engine.js').State} state */
export function validateCowEconomy(state){const g=state.cow;if(!g)return;const check=(/** @type {boolean} */ok,/** @type {string} */reason='Cow economy mismatch')=>{if(!ok)throw Error(reason);},lines=state.ledger.filter(l=>COW_LEDGER_TYPES.includes(l.type)||l.id.includes(':cow.')||l.id.startsWith('cow.')),rows=(/** @type {string} */type)=>lines.filter(l=>l.type===type);if(!g.visited){check(lines.length===0);return;}check(lines.every(l=>COW_LEDGER_TYPES.includes(l.type)));const starter=rows('cow_starter_grant');check(starter.length===1&&starter[0].id==='cow.starter.v1'&&starter[0].tick===g.enteredTick&&starter[0].amount===0&&lines[0]===starter[0]);const elapsed=state.tick-g.enteredTick;let previous=-1;for(const l of lines){check(l.tick>=g.enteredTick&&l.tick>=previous&&l.tick<=state.tick);previous=l.tick;if(l.type==='cow_starter_grant'||l.type==='cow_recovery_grant')continue;const revision=Number(l.id.split(':')[0]);check(Number.isSafeInteger(revision)&&revision>=1&&revision<=state.revision);}
const feed=rows('cow_feed_purchase');check(feed.every(l=>l.amount===-COW.feedBagPrice&&/^[1-9][0-9]*:cow\.feed$/.test(l.id))&&g.stats.feedBoughtG===feed.length*COW.feedBagG,'Cow feed purchase ledger mismatch');
const paid=(/** @type {string} */type,/** @type {boolean} */owned,/** @type {number} */price,/** @type {string} */suffix)=>{const list=rows(type);check(list.length===(owned?1:0)&&list.every(l=>l.amount===-price&&l.id===l.id.split(':')[0]+':cow.'+suffix));return list[0];};
paid('cow_trough_upgrade',!!g.barn?.troughUpgrade,COW.troughPrice,'trough');const cooler=paid('cow_cooler_purchase',g.cooler.owned,COW.coolerPrice,'cooler');paid('cow_shade_upgrade',!!g.barn?.shade,COW.shadePrice,'shade');paid('cow_sanitation_upgrade',!!g.barn?.sanitation,COW.sanitationPrice,'sanitation');const expansion=paid('cow_barn_upgrade',!!g.barn?.expanded,COW.expansionPrice,'barn'),purchase=paid('cow_purchase',g.stats.purchasedCows===1,COW.cowPrice,'purchase.1');for(const c of g.cows){if(c.id.startsWith('cow.starter.'))check(c.acquiredTick===g.enteredTick);else check(!!purchase&&!!expansion&&expansion.tick<=purchase.tick&&c.acquiredTick===purchase.tick&&!!g.purchaseProof&&g.purchaseProof.tick===purchase.tick);}
const energy=rows('cow_energy');check(energy.length===g.stats.energyPayments&&energy.every((l,i)=>l.amount===-COW.energyPrice&&l.id===l.id.split(':')[0]+':cow.energy:'+l.tick&&!!cooler&&l.tick>=cooler.tick&&(i===0||l.tick-energy[i-1].tick>=COW.energyTicks)));check(g.stats.energyUsedTicks<=elapsed&&g.cooler.status===cowCoolerStatus(state));
const sales=rows('cow_milk_sale');check(sales.length===g.stats.saleCount&&sales.every((l,i)=>l.id===l.id.split(':')[0]+':cow.sale:'+(i+1)&&l.amount>=0)&&sales.reduce((n,l)=>n+l.amount,0)===Math.floor(g.stats.milkValueNumerator/1000));let receiptId=g.nextSale-g.receipts.length,volume=0,numerator=0,priorRemainder=-1,priorTick=-1;for(const receipt of g.receipts){const row=sales[receipt.id-1],value=receipt.coins*1000+receipt.remainderAfter-receipt.remainderBefore;check(receipt.id===receiptId++&&!!row&&receipt.tick===row.tick&&receipt.coins===row.amount&&receipt.tick>=priorTick&&(priorRemainder<0||receipt.remainderBefore===priorRemainder)&&value>=receipt.volumeMl*3&&value<=receipt.volumeMl*6);if(receipt.orderId){const order=COW_ORDERS.find(o=>o.id===receipt.orderId);check(!!order&&g.orders.completedIds.includes(receipt.orderId)&&receipt.volumeMl===order?.volumeMl&&receipt.bonus===order?.bonus);}else check(receipt.bonus===0);volume+=receipt.volumeMl;numerator+=value;priorRemainder=receipt.remainderAfter;priorTick=receipt.tick;}check(volume<=g.soldMilkMl&&numerator<=g.stats.milkValueNumerator);if(g.receipts.length)check(g.receipts.at(-1)?.remainderAfter===g.milkRevenueRemainder);if(g.stats.saleCount<=COW.historyMax)check(volume===g.soldMilkMl&&numerator===g.stats.milkValueNumerator&&(!g.receipts.length||g.receipts[0].remainderBefore===0));
check(!g.orders.acceptedId||COW_ORDERS.some(o=>o.id===g.orders.acceptedId)&&g.grants.includes('cow.welcome')&&!g.orders.completedIds.includes(g.orders.acceptedId));check(g.orders.completedIds.every(id=>COW_ORDERS.some(o=>o.id===id)));const bonuses=rows('cow_order_bonus');check(bonuses.length===g.orders.completedIds.length);for(const id of g.orders.completedIds){const order=COW_ORDERS.find(o=>o.id===id),bonus=bonuses.filter(l=>l.id===l.id.split(':')[0]+':cow.order:'+id);check(!!order&&bonus.length===1&&bonus[0].amount===order?.bonus&&g.grants.includes('cow.welcome')&&sales.some(l=>l.tick===bonus[0].tick&&l.id.split(':')[0]===bonus[0].id.split(':')[0]));}
const jobs=rows('cow_recovery_grant');check(jobs.length===g.recovery.completed&&jobs.every((l,i)=>l.id==='cow.recovery.'+(i+1)&&l.amount===0&&l.tick>=g.enteredTick+COW.recoveryHours&&(i===0||l.tick-jobs[i-1].tick>=24)));if(jobs.length)check(jobs.at(-1)?.tick===g.recovery.lastCompleteTick);check(g.stats.recoveryFeedGrantedG<=jobs.reduce((n,l)=>n+(purchase&&lines.indexOf(l)>lines.indexOf(purchase)?3:2)*COW.feedDayG,0)&&g.stats.recoveryWaterGrantedMl<=jobs.reduce((n,l)=>n+(purchase&&lines.indexOf(l)>lines.indexOf(purchase)?3:2)*COW.hotWaterDayMl,0));if(!jobs.length)check(g.stats.recoveryFeedGrantedG===0&&g.stats.recoveryWaterGrantedMl===0);if(g.recovery.active)check(g.recovery.startedTick>=g.recovery.nextEligibleTick);else if(g.recovery.completed)check(g.recovery.lastCompleteTick-g.recovery.startedTick>=COW.recoveryHours);
for(const key of /** @type {const} */(['feedActions','waterActions','barnCleaned','standCleaned','canCleaned','inspected','milkings','discardCount','saleCount']))check(g.stats[key]<=state.revision);check(g.stats.discardCount<=g.stats.milkings&&(!g.mission.inspectedA||g.stats.inspected>0));const checks=[g.visited,g.stats.feedActions>0,g.stats.waterActions>0,g.stats.standCleaned>0,g.mission.inspectedA,g.stats.milkings>0,g.stats.saleCount>0,g.mission.upgradeViewed];let step=0;while(step<checks.length&&checks[step])step++;check(g.mission.step===step&&g.grants.includes('cow.welcome')===(step>=7));for(const id of g.grants){if(id==='cow.happy')check(g.stats.healthyHours>=72);if(id==='cow.cool')check(g.cooler.owned&&g.stats.cooledHours>=24);if(id==='cow.heat')check(!!g.barn?.shade&&g.stats.hotShadeHours>=24);if(id==='cow.bigger')check(!!g.barn?.expanded&&g.stats.purchasedCows===1&&g.cows.length===3);if(id==='cow.efficient')check(g.stats.saleCount>=10&&g.soldMilkMl>=50000);}
}
